from ansible.module_utils.facts.sysctl import get_sysctl


class FakeModule:
    def __init__(self, rc=0, output="", error=None):
        self.rc = rc
        self.output = output
        self.error = error
        self.bin_path_requests = []
        self.commands = []
        self.warnings = []

    def get_bin_path(self, name):
        self.bin_path_requests.append(name)
        return "/sbin/sysctl"

    def run_command(self, command):
        self.commands.append(command)
        if self.error is not None:
            raise self.error
        return self.rc, self.output, ""

    def warn(self, message):
        self.warnings.append(message)


def test_get_sysctl_parses_blank_and_multiline_values():
    module = FakeModule(
        output=(
            "\n"
            "kernel.alpha = one\n"
            " continuation\n"
            "kernel.beta: two\n"
            "kernel.gamma=three\n"
        )
    )

    result = get_sysctl(module, ["kernel", "vm"])

    assert module.bin_path_requests == ["sysctl"]
    assert module.commands == [["/sbin/sysctl", "kernel", "vm"]]
    assert result == {
        "kernel.alpha": "one\n continuation",
        "kernel.beta": "two",
        "kernel.gamma": "three",
    }
    assert module.warnings == []


def test_get_sysctl_warns_for_unparseable_lines():
    module = FakeModule(output="malformed line\nkernel.valid = yes\n")

    result = get_sysctl(module, [])

    assert result == {"kernel.valid": "yes"}
    assert len(module.warnings) == 1
    assert module.warnings[0].startswith(
        "Unable to split sysctl line (malformed line):"
    )


def test_get_sysctl_returns_empty_mapping_when_command_raises_oserror():
    module = FakeModule(error=OSError("cannot read sysctl"))

    result = get_sysctl(module, ["kernel"])

    assert module.bin_path_requests == ["sysctl"]
    assert module.commands == [["/sbin/sysctl", "kernel"]]
    assert result == {}
    assert module.warnings == ["Unable to read sysctl: cannot read sysctl"]


def test_get_sysctl_ignores_output_when_command_returns_nonzero():
    module = FakeModule(rc=1, output="kernel.value = ignored\n")

    result = get_sysctl(module, ["kernel"])

    assert result == {}
    assert module.warnings == []


def test_get_sysctl_returns_empty_mapping_for_only_blank_lines():
    module = FakeModule(output="\n \n\t\n")

    result = get_sysctl(module, [])

    assert result == {}
    assert module.warnings == []
